begin;
insert into auth.users(id,email,email_confirmed_at) values('cf000000-0000-4000-8000-000000000001','seedance-fast-fixture@example.invalid',now());
select public.ensure_signup_bonus('cf000000-0000-4000-8000-000000000001');
update public.credit_accounts set balance=1000,total_spent=0,total_refunded=0 where user_id='cf000000-0000-4000-8000-000000000001';
do $$
declare u uuid:='cf000000-0000-4000-8000-000000000001';o text:='user-'||u::text;
 rid uuid:=gen_random_uuid();r jsonb;before_balance numeric;before_tx bigint;
 p jsonb:='{"model":"seedance-2.0-fast","prompt":"fast fixture","duration":5,"resolution":"480p","size":"16:9","generate_audio":true,"return_last_frame":true,"nsfw_check":false}';
 refs jsonb:='[{"id":"v","kind":"video","duration_ms":3000,"width":854,"height":480},{"id":"a","kind":"audio","duration_ms":3000}]';
begin
 assert private.seedance20_fast_charge(.1992)=4.5 and private.seedance20_fast_charge(.428)=9.5;
 assert private.seedance20_charge(.33)=7.5 and private.seedance25_charge(.48)=11;
 r:=public.begin_seedance20_fast_job(o,u,rid,'platform','generate',repeat('a',64),p,'[]');
 assert (r->>'ok')::boolean and (r#>>'{job,estimated_credits}')::numeric=4.5 and (r#>>'{job,reserved_credits}')::numeric=7.5,r::text;
 assert r#>>'{job,pricing_profile,markup}'='1.2' and r#>>'{job,pricing_profile,version}'='seedance20fast-usd7-cny038-markup20-half-v1';
 assert (r->>'balance')::numeric=992.5;
 r:=public.begin_seedance20_fast_job(o,u,rid,'platform','generate',repeat('a',64),p,'[]');assert (r->>'existing')::boolean;
 assert (select balance from public.credit_accounts where user_id=u)=992.5;
 r:=public.begin_seedance20_fast_job(o,u,rid,'platform','generate',repeat('b',64),p,'[]');assert r->>'code'='VIDEO_REQUEST_CONFLICT';
 r:=public.apply_seedance20_job(o,rid,'completed',null,null,'[]',.1992);assert r->>'code'='VIDEO_NOT_FOUND';
 r:=public.apply_seedance20_fast_job('user-other',rid,'completed',null,null,'[]',.1992);assert r->>'code'='VIDEO_NOT_FOUND';
 r:=public.apply_seedance20_fast_job(o,rid,'submitted','task_fast_fixture_0001');
 r:=public.apply_seedance20_fast_job(o,rid,'completed');assert r#>>'{job,billing_status}'='awaiting_provider';
 assert (select total_spent from public.credit_accounts where user_id=u)=0;
 r:=public.apply_seedance20_fast_job(o,rid,'completed',null,null,'[]',.1992);assert (r#>>'{job,charged_credits}')::numeric=4.5 and (r->>'balance')::numeric=995.5;
 before_tx:=(select count(*) from public.credit_transactions where user_id=u);
 r:=public.apply_seedance20_fast_job(o,rid,'completed',null,null,'[]',1);
 r:=public.apply_seedance20_fast_job(o,rid,'failed');assert (r#>>'{job,charged_credits}')::numeric=4.5;
 assert (select count(*) from public.credit_transactions where user_id=u)=before_tx;
 rid:=gen_random_uuid();r:=public.begin_seedance20_fast_job(o,u,rid,'platform','generate',repeat('c',64),p,refs);
 assert (r#>>'{job,estimated_credits}')::numeric=4.5 and (r#>>'{job,reserved_credits}')::numeric=7;
 assert (r#>>'{job,reference_duration_ms}')::int=3000;
 before_balance:=(select balance+7 from public.credit_accounts where user_id=u);
 r:=public.apply_seedance20_fast_job(o,rid,'failed',null,'VIDEO_REFERENCE_DURATION');assert (r->>'balance')::numeric=before_balance;
 before_tx:=(select count(*) from public.credit_transactions where user_id=u);
 r:=public.apply_seedance20_fast_job(o,rid,'failed');assert (select count(*) from public.credit_transactions where user_id=u)=before_tx;
 rid:=gen_random_uuid();r:=public.begin_seedance20_fast_job(o,u,rid,'platform','generate',repeat('d',64),p||'{"resolution":"720p"}','[]');
 assert (r#>>'{job,estimated_credits}')::numeric=9.5 and (r#>>'{job,reserved_credits}')::numeric=15.5;
 r:=public.apply_seedance20_fast_job(o,rid,'completed',null,null,'[]',.428);assert (r#>>'{job,charged_credits}')::numeric=9.5;
 before_tx:=(select count(*) from public.credit_transactions where user_id=u);
 r:=public.begin_seedance20_fast_job(o,u,gen_random_uuid(),'platform','generate',repeat('a',64),p||'{"resolution":"1080p"}','[]');assert r->>'code'='INVALID_VIDEO_INPUT';
 r:=public.begin_seedance20_fast_job(o,u,gen_random_uuid(),'platform','generate',repeat('a',64),p||'{"resolution":"4k"}','[]');assert r->>'code'='INVALID_VIDEO_INPUT';
 assert (select count(*) from public.credit_transactions where user_id=u)=before_tx;
 rid:=gen_random_uuid();r:=public.begin_seedance20_fast_job(o,u,rid,'platform','generate',repeat('e',64),p,'[]');
 update public.credit_accounts set balance=0 where user_id=u;
 r:=public.apply_seedance20_fast_job(o,rid,'completed',null,null,'[]',1);assert r#>>'{job,billing_status}'='awaiting_balance' and (r->>'required_credits')::numeric=15;
 r:=public.begin_seedance20_fast_job(o,u,gen_random_uuid(),'platform','generate',repeat('f',64),p,'[]');assert r->>'code'='VIDEO_UNSETTLED_BALANCE';
 update public.credit_accounts set balance=15 where user_id=u;
 r:=public.apply_seedance20_fast_job(o,rid,'completed',null,null,'[]',.1);assert r#>>'{job,billing_status}'='settled' and (r#>>'{job,charged_credits}')::numeric=22.5;
 rid:=gen_random_uuid();r:=public.begin_seedance20_fast_job(o,u,rid,'own_key','generate',repeat('a',64),p,'[]');assert (r->>'ok')::boolean;
 r:=public.apply_seedance20_fast_job(o,rid,'completed');assert r#>>'{job,billing_status}'='not_applicable' and (r#>>'{job,charged_credits}')::numeric=0;
 assert not has_function_privilege('anon','public.begin_seedance20_fast_job(text,uuid,uuid,text,text,text,jsonb,jsonb)','EXECUTE');
 assert not has_function_privilege('authenticated','private.apply_seedance20_fast_job(text,uuid,text,text,text,jsonb,numeric,bigint)','EXECUTE');
 assert has_function_privilege('service_role','public.apply_seedance20_fast_job(text,uuid,text,text,text,jsonb,numeric,bigint)','EXECUTE');
end $$;
rollback;
